// On-device proof for align-L2 extract + argmin (shaders/corr.comp ops 0-1).
//
// Usage: srp_proof_corr <corr.spv> <ref_dir>
// Runs SrpCorrExtractGpu (op 0) and SrpCorrArgminGpu (op 1) on-device on the
// real-burst 512-crop level-1 pair (<ref_dir>/corr_{mov,flow,patches_cpu,
// corrs_cpu,dflow_cpu}{,_off}.npy + corr_params.txt, generated by
// /tmp/gen_corr_refs.py from the unmodified CPU source). Two cases per op:
// the true replay flow and a +2.5/-1.5 offset flow (all 225 tiles move;
// the .5 stresses banker's rounding in extract).
// Gates (gpu_l2_levels, never weakened): extract bit-exact vs
// extract_flow_patches; argmin winning (dx,dy) bit-exact vs the CPU argmin
// (integers-as-floats). Each op is proven independently (CPU oracles as the
// other op's input); a chained extract->argmin run closes the composition.
// Prints numbers; exits nonzero on any breach.

#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <functional>
#include <string>
#include <vector>

#include <vulkan/vulkan.h>

#include "npy.h"
#include "srp_context.h"
#include "srp_pipeline.h"

namespace {

bool FindMemoryType(VkPhysicalDevice physical, uint32_t type_bits,
                    VkMemoryPropertyFlags flags, uint32_t* out_index) {
  VkPhysicalDeviceMemoryProperties props{};
  vkGetPhysicalDeviceMemoryProperties(physical, &props);
  for (uint32_t i = 0; i < props.memoryTypeCount; ++i) {
    if ((type_bits & (1u << i)) != 0u &&
        (props.memoryTypes[i].propertyFlags & flags) == flags) {
      *out_index = i;
      return true;
    }
  }
  return false;
}

bool MakeBuffer(VkDevice device, VkPhysicalDevice physical, VkDeviceSize bytes,
                const float* src, VkBuffer* out_buffer,
                VkDeviceMemory* out_memory) {
  VkBufferCreateInfo buffer_info{};
  buffer_info.sType = VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO;
  buffer_info.size = bytes;
  buffer_info.usage = VK_BUFFER_USAGE_STORAGE_BUFFER_BIT;
  buffer_info.sharingMode = VK_SHARING_MODE_EXCLUSIVE;
  if (vkCreateBuffer(device, &buffer_info, nullptr, out_buffer) != VK_SUCCESS) {
    return false;
  }
  VkMemoryRequirements req{};
  vkGetBufferMemoryRequirements(device, *out_buffer, &req);
  uint32_t index = 0;
  if (!FindMemoryType(physical, req.memoryTypeBits,
                      VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT |
                          VK_MEMORY_PROPERTY_HOST_COHERENT_BIT,
                      &index)) {
    vkDestroyBuffer(device, *out_buffer, nullptr);
    return false;
  }
  VkMemoryAllocateInfo alloc{};
  alloc.sType = VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO;
  alloc.allocationSize = req.size;
  alloc.memoryTypeIndex = index;
  if (vkAllocateMemory(device, &alloc, nullptr, out_memory) != VK_SUCCESS) {
    vkDestroyBuffer(device, *out_buffer, nullptr);
    return false;
  }
  if (vkBindBufferMemory(device, *out_buffer, *out_memory, 0) != VK_SUCCESS) {
    vkFreeMemory(device, *out_memory, nullptr);
    vkDestroyBuffer(device, *out_buffer, nullptr);
    return false;
  }
  void* mapped = nullptr;
  if (vkMapMemory(device, *out_memory, 0, bytes, 0, &mapped) != VK_SUCCESS) {
    return false;
  }
  if (src != nullptr) {
    std::memcpy(mapped, src, static_cast<size_t>(bytes));
  } else {
    std::memset(mapped, 0, static_cast<size_t>(bytes));
  }
  vkUnmapMemory(device, *out_memory);
  return true;
}

void FreeBuffer(VkDevice device, VkBuffer buffer, VkDeviceMemory memory) {
  if (buffer != VK_NULL_HANDLE) vkDestroyBuffer(device, buffer, nullptr);
  if (memory != VK_NULL_HANDLE) vkFreeMemory(device, memory, nullptr);
}

std::vector<uint8_t> ReadFile(const char* path) {
  std::vector<uint8_t> bytes;
  if (FILE* f = std::fopen(path, "rb")) {
    std::fseek(f, 0, SEEK_END);
    const long n = std::ftell(f);
    std::fseek(f, 0, SEEK_SET);
    if (n > 0) {
      bytes.resize(static_cast<size_t>(n));
      bytes.resize(std::fread(bytes.data(), 1, bytes.size(), f));
    }
    std::fclose(f);
  }
  return bytes;
}

// Stages three caller vectors, runs `dispatch(a, b, c)`, reads the third
// (size out_n floats) back into `got`.
bool Run3(srp::Context* ctx,
          const std::function<srp::Status(VkBuffer, VkBuffer, VkBuffer)>&
              dispatch,
          const std::vector<float>& a, const std::vector<float>& b,
          size_t out_n, std::vector<float>* got) {
  auto* device = static_cast<VkDevice>(srp::NativeDevice(ctx));
  auto* physical = static_cast<VkPhysicalDevice>(srp::NativePhysicalDevice(ctx));
  VkBuffer abuf = VK_NULL_HANDLE, bbuf = VK_NULL_HANDLE,
           cbuf = VK_NULL_HANDLE;
  VkDeviceMemory amem = VK_NULL_HANDLE, bmem = VK_NULL_HANDLE,
                 cmem = VK_NULL_HANDLE;
  bool ok = false;
  if (MakeBuffer(device, physical, a.size() * sizeof(float), a.data(), &abuf,
                 &amem) &&
      MakeBuffer(device, physical, b.size() * sizeof(float), b.data(), &bbuf,
                 &bmem) &&
      MakeBuffer(device, physical,
                 static_cast<VkDeviceSize>(out_n) * sizeof(float), nullptr,
                 &cbuf, &cmem) &&
      dispatch(abuf, bbuf, cbuf) == srp::Status::kOk) {
    void* mapped = nullptr;
    if (vkMapMemory(device, cmem, 0,
                    static_cast<VkDeviceSize>(out_n) * sizeof(float), 0,
                    &mapped) == VK_SUCCESS) {
      got->assign(static_cast<const float*>(mapped),
                  static_cast<const float*>(mapped) + out_n);
      vkUnmapMemory(device, cmem);
      ok = true;
    }
  }
  FreeBuffer(device, abuf, amem);
  FreeBuffer(device, bbuf, bmem);
  FreeBuffer(device, cbuf, cmem);
  return ok;
}

bool CheckExact(const char* name, const std::vector<float>& got,
                const std::vector<float>& want) {
  if (got.size() != want.size()) {
    std::fprintf(stderr, "FAIL %s: size %zu vs %zu\n", name, got.size(),
                 want.size());
    return false;
  }
  uint64_t ndiff = 0;
  float maxabs = 0.0f;
  for (size_t i = 0; i < got.size(); ++i) {
    const float d = std::fabs(got[i] - want[i]);
    if (d != 0.0f) {
      ++ndiff;
      maxabs = std::fmax(maxabs, d);
    }
  }
  const bool pass = ndiff == 0;
  std::printf("%s: n=%zu ndiff=%llu maxabs=%.6g (bit-exact) %s\n", name,
              got.size(), static_cast<unsigned long long>(ndiff),
              static_cast<double>(maxabs), pass ? "PASS" : "FAIL");
  return pass;
}

}  // namespace

int main(int argc, char** argv) {
  if (argc != 3) {
    std::fprintf(stderr, "usage: %s <corr.spv> <ref_dir>\n", argv[0]);
    return 2;
  }
  const std::string ref_dir = argv[2];
  auto load = [&](const char* name, srp_proof::NpyArray* out) {
    return srp_proof::LoadNpy((ref_dir + "/" + name).c_str(), out);
  };

  srp_proof::NpyArray mov, flow, patches, corrs, dflow, flow_off,
      patches_off, corrs_off, dflow_off;
  if (!load("corr_mov.npy", &mov) || !load("corr_flow.npy", &flow) ||
      !load("corr_patches_cpu.npy", &patches) ||
      !load("corr_corrs_cpu.npy", &corrs) ||
      !load("corr_dflow_cpu.npy", &dflow) ||
      !load("corr_flow_off.npy", &flow_off) ||
      !load("corr_patches_cpu_off.npy", &patches_off) ||
      !load("corr_corrs_cpu_off.npy", &corrs_off) ||
      !load("corr_dflow_cpu_off.npy", &dflow_off)) {
    std::fprintf(stderr, "FAIL: corr refs missing\n");
    return 1;
  }
  uint32_t tile_size = 0, radius = 0;
  {
    const std::vector<uint8_t> text =
        ReadFile((ref_dir + "/corr_params.txt").c_str());
    if (text.empty() ||
        std::sscanf(reinterpret_cast<const char*>(text.data()),
                    "tile_size=%u search_radius=%u", &tile_size, &radius) !=
            2) {
      std::fprintf(stderr, "FAIL: cannot parse corr_params.txt\n");
      return 1;
    }
  }
  const uint32_t h = static_cast<uint32_t>(mov.shape[0]);
  const uint32_t w = static_cast<uint32_t>(mov.shape[1]);
  const uint32_t ntx = static_cast<uint32_t>(flow.shape[1]);
  const uint32_t nty = static_cast<uint32_t>(flow.shape[0]);
  const uint32_t tc = ntx * nty;
  const uint32_t s = tile_size + 2 * radius;
  const uint32_t c = 2 * radius + 1;
  std::printf("mov %ux%u tiles %ux%u=%u tile=%u radius=%u S=%u C=%u\n", w, h,
              ntx, nty, tc, tile_size, radius, s, c);

  srp::Context* ctx = nullptr;
  if (srp::Create(&ctx) != srp::Status::kOk || ctx == nullptr) {
    std::fprintf(stderr, "FAIL: srp::Create failed\n");
    return 1;
  }
  std::printf("device: %s\n", srp::DeviceInfo(ctx).c_str());
  auto* device = static_cast<VkDevice>(srp::NativeDevice(ctx));

  const std::vector<uint8_t> spirv = ReadFile(argv[1]);
  if (spirv.empty() || spirv.size() % 4 != 0) {
    std::fprintf(stderr, "FAIL: cannot read spv %s\n", argv[1]);
    srp::Destroy(ctx);
    return 1;
  }
  VkShaderModuleCreateInfo module_info{};
  module_info.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
  module_info.codeSize = spirv.size();
  module_info.pCode = reinterpret_cast<const uint32_t*>(spirv.data());
  VkShaderModule module = VK_NULL_HANDLE;
  if (vkCreateShaderModule(device, &module_info, nullptr, &module) != VK_SUCCESS) {
    std::fprintf(stderr, "FAIL: shader module create failed\n");
    srp::Destroy(ctx);
    return 1;
  }

  int failures = 0;
  std::vector<float> got;
  auto extract = [&](const std::vector<float>& fl,
                     std::vector<float>* out) {
    return Run3(ctx,
                [&](VkBuffer a, VkBuffer b, VkBuffer cc) {
                  return srp::SrpCorrExtractGpu(ctx, h, w, tc, tile_size,
                                               radius, ntx, a, b, cc, module);
                },
                mov.data, fl, static_cast<size_t>(tc) * s * s, out);
  };
  auto argmin = [&](const std::vector<float>& pa,
                    const std::vector<float>& co, std::vector<float>* out) {
    return Run3(ctx,
                [&](VkBuffer a, VkBuffer b, VkBuffer cc) {
                  return srp::SrpCorrArgminGpu(
                      ctx, tc, tile_size, radius, ntx,
                      static_cast<uint32_t>(pa.size()),
                      static_cast<uint32_t>(co.size()), a, b, cc, module);
                },
                pa, co, static_cast<size_t>(tc) * 2, out);
  };

  if (!extract(flow.data, &got) ||
      !CheckExact("corrExtract_replay", got, patches.data)) {
    ++failures;
  }
  if (!extract(flow_off.data, &got) ||
      !CheckExact("corrExtract_off", got, patches_off.data)) {
    ++failures;
  }
  if (!argmin(patches.data, corrs.data, &got) ||
      !CheckExact("corrArgmin_replay", got, dflow.data)) {
    ++failures;
  }
  std::vector<float> gpu_patches;
  if (!argmin(patches_off.data, corrs_off.data, &got) ||
      !CheckExact("corrArgmin_off", got, dflow_off.data)) {
    ++failures;
  } else if (!extract(flow_off.data, &gpu_patches) ||
             !argmin(gpu_patches, corrs_off.data, &got) ||
             !CheckExact("corrChained_off", got, dflow_off.data)) {
    ++failures;
  }

  vkDestroyShaderModule(device, module, nullptr);
  srp::Destroy(ctx);
  if (failures == 0) std::printf("PASS: corr extract+argmin on-device exact\n");
  return failures == 0 ? 0 : 1;
}
